google.charts.load('current',{'packages':['corechart']});google.charts.setOnLoadCallback(drawChart_overall_stats_easy);function drawChart_overall_stats_easy(){var data=google.visualization.arrayToDataTable(pandemic_graph_data);var options={pieHole:0.5,pieSliceTextStyle:{color:'#FFFFFF',},pieSliceText:'value',slices:{0:{color:'#FF000A'},1:{color:'#FF7308'},2:{color:'#38ED1C'},3:{color:'#EFFF00'},4:{color:'transparent'}},pieSliceBorderColor:'transparent',backgroundColor:'transparent',chartArea:{left:0,top:0,width:'100%',height:'90%',},pieStartAngle:-90,legend:{alignment:'center',position:'bottom',textStyle:{color:'#000000',bold:true,},},tooltip:{trigger:'focus',showColorCode:true,text:'value',},};var chart_overall_stats_easy=new google.visualization.PieChart(document.getElementById('easy-overall-stats'));chart_overall_stats_easy.draw(data,options);$("#google-visualization-errors-all-1").hide();$("#google-visualization-errors-0").hide();};